package cn.zj.zjmarket.infrastructure.adapter.repository;
import cn.zj.zjmarket.domain.refund.adapter.repository.*;
import cn.zj.zjmarket.domain.refund.model.Refund;
import cn.zj.zjmarket.domain.order.model.valobj.PurchaseConditions;
import cn.zj.zjmarket.types.exception.*;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.dao.DuplicateKeyException;
import javax.sql.DataSource;
import java.util.*;
import java.util.function.Supplier;

/** Read projections never claim work. Operator controls only wake existing, qualified work. */
public final class RefundOperationsRepository implements IRefundOperations,IRefundView {
 private final JdbcTemplate db;private RefundRepository refunds;private final TransactionTemplate read;private final ObjectMapper json=new ObjectMapper();
 public RefundOperationsRepository(DataSource ds,RefundRepository refunds){db=new JdbcTemplate(ds);this.refunds=refunds;read=new TransactionTemplate(new DataSourceTransactionManager(ds));read.setReadOnly(true);read.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);read.setTimeout(10);}
 public void enableRecovery(RefundRepository refunds){this.refunds=refunds;}
 private <T>T snapshot(Supplier<T> action){return read.execute(s->action.get());}
 private Map<String,Object> row(String sql,Object...a){var rs=db.queryForList(sql,a);return rs.isEmpty()?null:rs.getFirst();}
 private static long number(Map<String,Object> r,String key){return r.get(key)==null?0:((Number)r.get(key)).longValue();}
 private static String time(Object value){return value==null?null:cn.zj.zjmarket.domain.payment.service.impl.PaymentService.time(((Number)value).longValue());}
 private void operator(String actor){if(db.queryForObject("SELECT COUNT(*) FROM b_user_role WHERE user_id=? AND role='OPERATOR'",Long.class,actor)!=1)throw new AuthFailure(403,"FORBIDDEN");}
 private static void id(String id){if(id==null||!id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,63}"))throw PurchaseConditions.invalid();}
 private static String digest(byte[] b){try{return ContractCodec.sha256(b);}catch(Exception e){throw new IllegalStateException(e);}}
 private static byte[] bytes(Object o){try{return new ContractCodec().encode(o);}catch(Exception e){throw new IllegalStateException(e);}}
 public Map<String,Object> summary(String actor,String order){id(order);return snapshot(()->{if(row("SELECT order_id FROM b_market_order WHERE order_id=? AND user_id=?",order,actor)==null)throw new OrderFailure(404,"ORDER_NOT_FOUND");var f=row("SELECT * FROM b_refund WHERE order_id=?",order);return f==null?null:project(f,false);});}
 private Map<String,Object> project(Map<String,Object> f,boolean detail){var v=new LinkedHashMap<String,Object>();for(var key:Map.of("refundId","refund_id","orderId","order_id","paymentId","payment_id","fundsStatus","funds_status","syncStatus","sync_status","releaseStatus","release_status").entrySet())v.put(key.getKey(),f.get(key.getValue()));v.put("refundAmount",f.get("amount").toString());v.put("currency","CNY");v.put("version",Long.toString(number(f,"version")));v.put("refundedAt",time(f.get("refunded_at_ms")));if(!detail)return v;
  var task=row("SELECT * FROM b_refund_task WHERE refund_id=?",f.get("refund_id"));var a=f.get("current_attempt_id")==null?null:row("SELECT * FROM b_refund_attempt WHERE attempt_id=?",f.get("current_attempt_id"));v.put("eligibilityStatus",f.get("eligibility_status"));v.put("attemptId",f.get("current_attempt_id"));v.put("attemptStatus",a==null?"NONE":a.get("state"));v.put("refundVersion",number(f,"fact_version")==0?null:Long.toString(number(f,"fact_version")));v.put("acceptedRefundVersion",number(f,"accepted_version")==0?null:Long.toString(number(f,"accepted_version")));v.put("failureCode",f.get("release_error")!=null?f.get("release_error"):f.get("sync_error")!=null?f.get("sync_error"):task==null?null:task.get("last_error"));v.put("failureCount",task==null?0:number(task,"failure_count")+number(task,"business_failures"));v.put("alerted",task!=null&&Boolean.TRUE.equals(task.get("alerted")));v.put("nextAttemptAt",task==null?null:time(task.get("next_attempt_ms")));v.put("reasons",db.queryForList("SELECT DISTINCT j.reason FROM b_trade_work w JOIN JSON_TABLE(w.reasons,'$[*]' COLUMNS(reason VARCHAR(256) PATH '$')) j WHERE w.order_id=? ORDER BY 1",String.class,f.get("order_id")));v.put("evidenceIds",db.queryForList("SELECT DISTINCT e.inbox_id FROM b_trade_evidence_link e JOIN b_trade_work w ON w.work_id=e.work_id WHERE w.order_id=? ORDER BY e.inbox_id",String.class,f.get("order_id")));v.put("allowedActions",retryAllowed(f,task,a)?List.of("CHECK","RETRY"):List.of("CHECK"));return v;
 }
 private boolean retryAllowed(Map<String,Object> f,Map<String,Object> t,Map<String,Object> a){return !"REVIEW_REQUIRED".equals(f.get("sync_status"))&&!"REVIEW_REQUIRED".equals(f.get("release_status"))&&"ELIGIBLE".equals(f.get("eligibility_status"))&&"FAILED".equals(f.get("funds_status"))&&a!=null&&"FAILED".equals(a.get("state"))&&t!=null&&Set.of("READY","WAITING_DEPENDENCY").contains(t.get("state"))&&!Boolean.TRUE.equals(t.get("check_only"))&&t.get("lease_token")==null;}
 public Map<String,Object> refund(String actor,String id){operator(actor);id(id);return snapshot(()->{var f=row("SELECT * FROM b_refund WHERE refund_id=?",id);if(f==null)throw new OrderFailure(404,"REFUND_NOT_FOUND");return project(f,true);});}
 private static int page(Map<String,String> f,String k,int fallback,int max){String v=f.get(k);if(v==null)return fallback;if(!v.matches("[0-9]{1,6}"))throw PurchaseConditions.invalid();int n=Integer.parseInt(v);if(n<0||n>max||k.equals("size")&&n==0)throw PurchaseConditions.invalid();return n;}
 private Map<String,Object> list(Map<String,String> f,boolean reconciliation){int page=page(f,"page",0,100000),size=page(f,"size",20,100);String table=reconciliation?"b_reconciliation_task t":"b_refund t LEFT JOIN b_refund_task rt ON rt.refund_id=t.refund_id";StringBuilder where=new StringBuilder(" WHERE 1=1");List<Object> args=new ArrayList<>();Map<String,String> fields=reconciliation?Map.of("state","t.state","teamId","t.team_id","alerted","t.alerted"):Map.of("fundsStatus","t.funds_status","syncStatus","t.sync_status","releaseStatus","t.release_status","alerted","COALESCE(rt.alerted,FALSE)","orderId","t.order_id");for(var e:f.entrySet()){if(Set.of("page","size").contains(e.getKey()))continue;if(!fields.containsKey(e.getKey()))throw PurchaseConditions.invalid();String value=e.getValue();if(e.getKey().equals("alerted")){if(!Set.of("true","false").contains(value))throw PurchaseConditions.invalid();args.add(Boolean.valueOf(value));}else{if(e.getKey().endsWith("Id"))id(value);else{Set<String> values=switch(e.getKey()){case "fundsStatus"->Set.of("NONE","PENDING","UNKNOWN","FAILED","SUCCEEDED");case "syncStatus"->Set.of("NOT_CREATED","PENDING","ACCEPTED","WAITING_DEPENDENCY","REVIEW_REQUIRED");case "releaseStatus"->Set.of("HELD","READY","RELEASED","ALREADY_RELEASED","REVIEW_REQUIRED");default->Set.of("DISCOVERED","COLLECTING","READY","SUBMITTING","SUBMIT_UNKNOWN","WAITING_DEPENDENCY","RESOLVED","REVIEW_REQUIRED");};if(!values.contains(value))throw PurchaseConditions.invalid();}args.add(value);}where.append(" AND ").append(fields.get(e.getKey())).append("=?");}
  long total=db.queryForObject("SELECT COUNT(*) FROM "+table+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var rows=db.queryForList("SELECT t.* FROM "+table+where+" ORDER BY t.updated_at_ms DESC,t."+(reconciliation?"task_id":"refund_id")+" LIMIT ? OFFSET ?",args.toArray());return Map.of("page",page,"size",size,"total",total,"items",rows.stream().map(t->reconciliation?recon(t,false):project(t,false)).toList());}
 public Map<String,Object> refunds(String actor,Map<String,String> filters){operator(actor);return snapshot(()->list(filters,false));}
 public Map<String,Object> reconciliations(String actor,Map<String,String> filters){operator(actor);return snapshot(()->list(filters,true));}
 private Map<String,Object> recon(Map<String,Object> t,boolean detail){var v=new LinkedHashMap<String,Object>();v.put("taskId",t.get("task_id"));v.put("teamId",t.get("team_id"));v.put("reconciliationId",t.get("reconciliation_id"));v.put("rosterVersion",t.get("roster_version")==null?null:t.get("roster_version").toString());v.put("teamVersion",t.get("team_version")==null?null:t.get("team_version").toString());v.put("state",t.get("state"));v.put("version",Long.toString(number(t,"intent_version")));v.put("alerted",Boolean.TRUE.equals(t.get("alerted")));var members=db.queryForList("SELECT * FROM b_reconciliation_member WHERE task_id=? ORDER BY out_trade_no",t.get("task_id"));v.put("memberCount",members.size());v.put("readyCount",members.stream().filter(m->Set.of("PAID_ACCEPTED","CLOSED_UNPAID","PAID_OUTSIDE_WINDOW").contains(m.get("state"))).count());if(detail){var submission=row("SELECT * FROM b_reconciliation_submission WHERE task_id=?",t.get("task_id"));v.put("completionId",submission==null?null:submission.get("completion_id"));v.put("submissionState",submission==null?"NONE":submission.get("state"));v.put("members",members.stream().map(m->{var item=new LinkedHashMap<String,Object>();item.put("outTradeNo",m.get("out_trade_no"));item.put("userId",m.get("user_id"));item.put("localOrderId",m.get("local_order_id"));item.put("state",m.get("state"));var f=row("SELECT refund_id FROM b_refund WHERE order_id=?",m.get("local_order_id"));item.put("refundId",f==null?null:f.get("refund_id"));item.put("failureCode",m.get("last_error"));return item;}).toList());v.put("evidenceIds",db.queryForList("SELECT DISTINCT l.inbox_id FROM b_trade_evidence_link l JOIN b_trade_work w ON w.work_id=l.work_id WHERE w.team_id=? ORDER BY l.inbox_id",String.class,t.get("team_id")));}return v;}
 public Map<String,Object> reconciliation(String actor,String id){operator(actor);id(id);return snapshot(()->{var t=row("SELECT * FROM b_reconciliation_task WHERE task_id=?",id);if(t==null)throw new OrderFailure(404,"RECONCILIATION_NOT_FOUND");return recon(t,true);});}
 @SuppressWarnings("unchecked") private Result replay(String actor,String operation,String hash){var old=row("SELECT * FROM b_refund_operation WHERE actor_id=? AND operation_id=?",actor,operation);if(old==null)return null;if(!hash.equals(old.get("request_hash")))throw new OrderFailure(409,"IDEMPOTENCY_CONFLICT");byte[] raw=(byte[])old.get("result");if(!digest(raw).equals(old.get("result_hash")))throw new OrderFailure(409,"OPERATION_EVIDENCE_CONFLICT");try{return new Result(true,json.readValue(raw,Map.class));}catch(Exception e){throw new IllegalStateException(e);}}
 public Result control(String actor,String id,Control c){operator(actor);id(id);id(c.operationId());if(!Set.of("CHECK","RETRY").contains(c.action())||c.expectedVersion()<=0||c.reason()==null||c.reason().isBlank()||c.reason().codePointCount(0,c.reason().length())>256||c.reason().codePoints().anyMatch(Character::isISOControl))throw PurchaseConditions.invalid();String requestHash=digest(bytes(Map.of("refundId",id,"operationId",c.operationId(),"action",c.action(),"expectedVersion",Long.toString(c.expectedVersion()),"reason",c.reason())));Result old=replay(actor,c.operationId(),requestHash);if(old!=null)return old;if(refunds==null)throw new OrderFailure(503,"REFUND_RECOVERY_DISABLED");Result[] result={null};try{refunds.withLocked(id,()->{operator(actor);var previous=replay(actor,c.operationId(),requestHash);if(previous!=null){result[0]=previous;return;}var f=row("SELECT * FROM b_refund WHERE refund_id=?",id);if(!refunds.scoped(f))throw new OrderFailure(409,"REFUND_SCOPE_CONFLICT");refunds.lockQualification(f);var t=row("SELECT * FROM b_refund_task WHERE refund_id=?",id);var a=f.get("current_attempt_id")==null?null:row("SELECT * FROM b_refund_attempt WHERE attempt_id=?",f.get("current_attempt_id"));if(number(f,"version")!=c.expectedVersion())throw new OrderFailure(409,"VERSION_CONFLICT");long n=db.queryForObject("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)",Long.class);boolean wake=false;
   if(c.action().equals("RETRY")){if(!retryAllowed(f,t,a))throw new OrderFailure(409,"REFUND_RETRY_NOT_ALLOWED");try{refunds.eligible(f,refunds.cursor(f));}catch(IllegalArgumentException e){throw new OrderFailure(409,"REFUND_ELIGIBILITY_CONFLICT");}db.update("UPDATE b_refund_task SET state='READY',next_attempt_ms=?,intent_version=intent_version+1,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",n,n,id);wake=true;}
   else{if(t!=null&&a!=null&&!"LEASED".equals(t.get("state"))&&!Boolean.TRUE.equals(t.get("check_only"))){db.update("UPDATE b_refund_task SET check_previous_state=state,check_previous_due_ms=next_attempt_ms,check_only=TRUE,state='READY',next_attempt_ms=?,intent_version=intent_version+1,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",n,n,id);wake=true;}if(db.update("UPDATE b_trade_outbox SET next_attempt_ms=? WHERE refund_id=? AND state='PUBLISHED' AND lease_token IS NULL",n,id)>0)wake=true;}
   if(wake)db.update("UPDATE b_refund SET version=version+1,updated_at_ms=? WHERE refund_id=?",n,id);var receipt=Map.<String,Object>of("operationId",c.operationId(),"refundId",id,"action",c.action(),"state",wake?"ACCEPTED":"NO_CHANGE","version",Long.toString(number(f,"version")+(wake?1:0)));byte[] raw=bytes(receipt);db.update("INSERT INTO b_refund_operation(actor_id,operation_id,refund_id,action,expected_version,reason,request_hash,result,result_hash,created_at_ms) VALUES(?,?,?,?,?,?,?,?,?,?)",actor,c.operationId(),id,c.action(),c.expectedVersion(),c.reason(),requestHash,raw,digest(raw),n);result[0]=new Result(false,receipt);
  });}catch(DuplicateKeyException race){var original=replay(actor,c.operationId(),requestHash);if(original==null)throw race;return original;}if(result[0]==null)throw new OrderFailure(404,"REFUND_NOT_FOUND");return result[0];}
}
